use super::*;
use crate::settings::EffectFixture;
#[tokio::test]async fn system_io_actions_are_unavailable_while_reads_and_observations_remain_available(){
 let _serial=SERIAL.lock().await;stopped().await;let io=EffectFixture::new();let mut f=Fixture::start(vec![Step::enable_read(false),Step::enable_read(false)]);f.native=f.native.clone().with_effect_probe(io.probe.clone());let(ex,client,_,_owner,window)=launch(&f,l::Config::default());
 accepted_read(&client,&window).await;let original=client.view(&window).await.unwrap();let scope=original.scan_scope.unwrap();assert!(original.capabilities.scan);io.external();
 let view=client.view(&window).await.unwrap();assert!(view.data.is_some()&&view.capabilities.read);assert!(!view.capabilities.scan&&!view.capabilities.enable_wifi&&!view.capabilities.disable_wifi);assert!(view.scan_scope.is_none()&&view.enable_wifi_scope.is_none()&&view.disable_wifi_scope.is_none());
 expect(client.scan(&window,&scope,"unknown-scan").await,l::Reason::NativeUnavailable);expect(client.enable_wifi(&window,&scope,"unknown-enable").await,l::Reason::NativeUnavailable);expect(client.disable_wifi(&window,&scope,"unknown-disable").await,l::Reason::NativeUnavailable);
 accepted_read(&client,&window).await;assert_eq!(f.count("network.getState").await,2);assert_eq!(f.requests.lock().unwrap().len(),2);ex.shutdown().await;
}
#[tokio::test]async fn system_io_is_rechecked_after_native_greeting_before_each_mutating_writer(){
 for kind in 0..3{let _serial=SERIAL.lock().await;stopped().await;let io=EffectFixture::new();let gate=Arc::new(Notify::new());let read=if kind==2{Step::disable_read(true)}else{Step::enable_read(false)};let mut action=match kind{0=>Step::scan(),1=>Step::enable_ack(),_=>Step::disable_ack()};action.greeting_gate=Some(gate.clone());let mut f=Fixture::start(vec![read,action]);f.native=f.native.clone().with_effect_probe(io.probe.clone());let(ex,client,_,_owner,window)=launch(&f,l::Config::default());
  accepted_read(&client,&window).await;let view=client.view(&window).await.unwrap();let ticket=match kind{0=>client.scan(&window,&view.scan_scope.unwrap(),"late-scan").await.unwrap(),1=>client.enable_wifi(&window,&view.enable_wifi_scope.unwrap(),"late-enable").await.unwrap(),_=>client.disable_wifi(&window,&view.disable_wifi_scope.unwrap(),"late-disable").await.unwrap()};
  tokio::time::timeout(Duration::from_secs(3),async{while f.connections.load(Ordering::Relaxed)<2{tokio::time::sleep(Duration::from_millis(1)).await;}}).await.unwrap();io.external();assert!(inspection(&client).await.active);gate.notify_one();idle(&client).await;
  let done=client.ticket(&window,&ticket.id).await.unwrap();assert_eq!(done.phase,l::Phase::Failed);assert_eq!(done.reason,Some(l::Reason::NativeUnavailable));assert!(!done.effect_confirmed);assert_eq!(f.requests.lock().unwrap().len(),1);ex.shutdown().await;
 }
}
#[tokio::test]async fn system_io_loss_during_ack_wait_preserves_observed_ack_without_starting_another_effect(){
 let _serial=SERIAL.lock().await;stopped().await;let io=EffectFixture::new();let gate=Arc::new(Notify::new());let mut action=Step::enable_ack();action.reply_gate=Some(gate.clone());let mut f=Fixture::start(vec![Step::enable_read(false),action]);f.native=f.native.clone().with_effect_probe(io.probe.clone());let(ex,client,_,_owner,window)=launch(&f,l::Config::default());let scope=enable_actor_scope(&client,&window).await;let ticket=client.enable_wifi(&window,&scope,"ack-original").await.unwrap();f.wait_requests(2).await;io.external();
 assert!(inspection(&client).await.active);gate.notify_one();idle(&client).await;let done=client.ticket(&window,&ticket.id).await.unwrap();assert_eq!(done.phase,l::Phase::Acknowledged);assert!(!done.effect_confirmed&&done.refresh_recommended);expect(client.enable_wifi(&window,&scope,"no-next").await,l::Reason::NativeUnavailable);assert_eq!(f.requests.lock().unwrap().len(),2);ex.shutdown().await;
}
#[tokio::test]async fn system_io_loss_never_blocks_stop_or_releases_physical_slot_before_worker_drain(){
 let _serial=SERIAL.lock().await;stopped().await;let io=EffectFixture::new();let gate=Arc::new(Notify::new());let mut action=Step::enable_ack();action.reply_gate=Some(gate.clone());let mut f=Fixture::start(vec![Step::enable_read(false),action]);f.native=f.native.clone().with_effect_probe(io.probe.clone());let(ex,client,_,_owner,window)=launch(&f,l::Config::default());let scope=enable_actor_scope(&client,&window).await;let ticket=client.enable_wifi(&window,&scope,"stop-original").await.unwrap();f.wait_requests(2).await;io.external();
 let stopped=client.cancel(&window,&ticket.id).await.unwrap();assert_eq!(stopped.phase,l::Phase::Unknown);assert!(inspection(&client).await.active);expect(client.read(&window,true).await,l::Reason::Busy);gate.notify_one();idle(&client).await;assert_eq!(client.ticket(&window,&ticket.id).await.unwrap().phase,l::Phase::Unknown);assert_eq!(f.requests.lock().unwrap().len(),2);ex.shutdown().await;
}
#[tokio::test]async fn system_io_benign_commit_during_native_wait_keeps_captured_scope_and_destination(){
 let _serial=SERIAL.lock().await;stopped().await;let io=EffectFixture::new();let gate=Arc::new(Notify::new());let mut action=Step::enable_ack();action.greeting_gate=Some(gate.clone());let mut f=Fixture::start(vec![Step::enable_read(false),action]);f.native=f.native.clone().with_effect_probe(io.probe.clone());let(ex,client,_,_owner,window)=launch(&f,l::Config::default());let scope=enable_actor_scope(&client,&window).await;let ticket=client.enable_wifi(&window,&scope,"same-intent").await.unwrap();io.save();gate.notify_one();idle(&client).await;assert_eq!(client.ticket(&window,&ticket.id).await.unwrap().phase,l::Phase::Acknowledged);assert_eq!(f.count("network.wifi.enable").await,1);ex.shutdown().await;
}
